from __future__ import annotations; import asyncio; import contextlib; import hashlib; from dataclasses import dataclass; from datetime import UTC, date, datetime; from decimal import Decimal; from uuid import UUID, uuid4; import pytest; from sqlalchemy import select, text; from sqlalchemy.ext.asyncio import AsyncSession, async_sessionmaker; from src.extraction import BankStatementStatus, UploadedDocument; from src.extraction.base.types import RetireStatementCommand; from src.extraction.extension.source_lifecycle import retire_statement; from src.extraction.extension.statement_posting import try_auto_approve_high_confidence_statement; from src.extraction.extension.statement_workflow import reject_statement_workflow; from src.extraction.orm.layer2 import AtomicTransaction; from src.extraction.orm.reviewed_statement_envelope import StatementExtractionResultRecord; from src.extraction.orm.statement_summary import StatementSummary; from src.ledger import Account, AccountType, JournalEntry, JournalEntryStatus; from src.reconciliation import ReconciliationMatch, ReconciliationStatus, execute_matching; from tests.api._statement_router_fixtures import add_reviewed_disposition_rule, add_txn, build_statement, create_statement_account, seed_uploaded_document; from tests.reconciliation.test_transfer_integration import _seed_statement, _seed_txn; from tests.statement_ingestion import posting_dependencies
@dataclass(frozen=True)
class SharedRow: original_id: UUID; duplicate_id: UUID; txn_id: UUID; entry_id: UUID
async def _status_of(db: AsyncSession, statement_id: UUID) -> BankStatementStatus: return (await db.execute(select(StatementSummary.status).where(StatementSummary.id == statement_id))).scalar_one()
async def _entry_status(db: AsyncSession, entry_id: UUID) -> JournalEntryStatus: return (await db.execute(select(JournalEntry.status).where(JournalEntry.id == entry_id))).scalar_one()
async def _statement_id_of(db: AsyncSession, document: UploadedDocument) -> UUID: return (await db.execute(select(StatementSummary.id).where(StatementSummary.uploaded_document_id == document.id))).scalar_one()
async def _match_status(db: AsyncSession, txn_id: UUID) -> ReconciliationStatus: return (await db.execute(select(ReconciliationMatch.status).where(ReconciliationMatch.atomic_txn_id == txn_id))).scalar_one()
async def _reversal_ids(db: AsyncSession, entry_id: UUID) -> list[UUID]: result = await db.execute(select(JournalEntry.id).where(JournalEntry.source_id == entry_id)); return list(result.scalars().all())
async def _share_row(db: AsyncSession, txn: AtomicTransaction, other_document: UploadedDocument) -> None: txn.source_documents = [*txn.source_documents, {'doc_id': str(other_document.id), 'doc_type': 'bank_statement'}]; await db.flush()
async def _seed_posted_original_and_duplicate(db: AsyncSession, user_id: UUID, *, duplicate_status: BankStatementStatus) -> SharedRow: bank_account = await create_statement_account(db, user_id, 'DBS Release Ownership'); original = build_statement(user_id, f'release-original-{uuid4().hex}', 90); original.status = BankStatementStatus.APPROVED; original.account_id = bank_account.id; original.closing_balance = Decimal('120.00'); db.add(original); await db.flush(); txn = await add_txn(db, original, txn_date=date(2025, 1, 8), description='Salary', amount=Decimal('20.00'), direction='IN'); await add_reviewed_disposition_rule(db, user_id=user_id, keyword='salary', account_type=AccountType.INCOME, category='SALARY'); await db.commit(); posted = await try_auto_approve_high_confidence_statement(db, original.id, user_id, dependencies=posting_dependencies()); assert posted == 1; entry_id = (await db.execute(select(JournalEntry.id).where(JournalEntry.user_id == user_id, JournalEntry.source_id == txn.id, JournalEntry.status != JournalEntryStatus.VOID))).scalar_one(); duplicate = build_statement(user_id, f'release-duplicate-{uuid4().hex}', 90); duplicate.status = duplicate_status; duplicate.account_id = bank_account.id; duplicate.closing_balance = Decimal('120.00'); db.add(duplicate); await db.flush(); duplicate_document = await seed_uploaded_document(db, duplicate); await _share_row(db, txn, duplicate_document); await db.commit(); return SharedRow(original_id=original.id, duplicate_id=duplicate.id, txn_id=txn.id, entry_id=entry_id)
async def _seed_statement_with_unreadable_result(db: AsyncSession, user_id: UUID, *, status: BankStatementStatus) -> UUID: bank_account = await create_statement_account(db, user_id, 'DBS Unreadable Result'); statement = build_statement(user_id, f'release-unreadable-{uuid4().hex}', 90); statement.status = status; statement.account_id = bank_account.id; db.add(statement); await db.flush(); await seed_uploaded_document(db, statement); record_id = uuid4(); db.add(StatementExtractionResultRecord(id=record_id, user_id=user_id, statement_id=statement.id, content_digest=hashlib.sha256(record_id.bytes).hexdigest(), source_content_digest=statement.file_hash.ljust(64, '0')[:64], schema_version='999', producer_version='test-v1', payload={'schema_version': '999'}, source_trace_record_id=uuid4(), created_at=datetime.now(UTC))); await db.flush(); statement.current_extraction_result_id = record_id; await db.commit(); return statement.id
async def test_AC_extraction_2888_1_reject_of_duplicate_keeps_entries_of_the_approved_original(db: AsyncSession, test_user): 'AC-extraction.2888.1'; shared = await _seed_posted_original_and_duplicate(db, test_user.id, duplicate_status=BankStatementStatus.PARSED); assert await _entry_status(db, shared.entry_id) is JournalEntryStatus.POSTED; rejected = await reject_statement_workflow(db, shared.duplicate_id, test_user.id, dependencies=posting_dependencies()); assert rejected.status is BankStatementStatus.REJECTED; assert await _entry_status(db, shared.entry_id) is JournalEntryStatus.POSTED; assert await _reversal_ids(db, shared.entry_id) == []; assert await _status_of(db, shared.original_id) is BankStatementStatus.APPROVED
async def test_retire_of_approved_original_voids_entries_when_only_a_pending_duplicate_remains(db: AsyncSession, test_user): 'AC-extraction.2888.1'; shared = await _seed_posted_original_and_duplicate(db, test_user.id, duplicate_status=BankStatementStatus.PARSED); await retire_statement(db, RetireStatementCommand(statement_id=shared.original_id, user_id=test_user.id), dependencies=posting_dependencies()); assert await _status_of(db, shared.original_id) is BankStatementStatus.RETIRED; assert await _entry_status(db, shared.entry_id) is JournalEntryStatus.VOID; assert len(await _reversal_ids(db, shared.entry_id)) == 1
async def test_reject_of_approved_original_voids_entries_when_only_a_pending_duplicate_remains(db: AsyncSession, test_user): 'AC-extraction.2888.1'; shared = await _seed_posted_original_and_duplicate(db, test_user.id, duplicate_status=BankStatementStatus.PARSED); rejected = await reject_statement_workflow(db, shared.original_id, test_user.id, dependencies=posting_dependencies()); assert rejected.status is BankStatementStatus.REJECTED; assert await _entry_status(db, shared.entry_id) is JournalEntryStatus.VOID; assert await _status_of(db, shared.duplicate_id) is BankStatementStatus.PARSED
async def test_retire_of_one_of_two_approved_statements_keeps_the_shared_entry(db: AsyncSession, test_user): 'AC-extraction.2888.1'; shared = await _seed_posted_original_and_duplicate(db, test_user.id, duplicate_status=BankStatementStatus.APPROVED); await retire_statement(db, RetireStatementCommand(statement_id=shared.original_id, user_id=test_user.id), dependencies=posting_dependencies()); assert await _entry_status(db, shared.entry_id) is JournalEntryStatus.POSTED; assert await _reversal_ids(db, shared.entry_id) == []; await retire_statement(db, RetireStatementCommand(statement_id=shared.duplicate_id, user_id=test_user.id), dependencies=posting_dependencies()); assert await _entry_status(db, shared.entry_id) is JournalEntryStatus.VOID; assert len(await _reversal_ids(db, shared.entry_id)) == 1
async def test_reject_of_pending_duplicate_keeps_pre_approval_entries_of_pending_sibling(db: AsyncSession, test_user): 'AC-extraction.2888.1'; user_id = test_user.id; cash = Account(user_id=user_id, name='Cash', code='1001', type=AccountType.ASSET, currency='SGD'); checking = Account(user_id=user_id, name='Checking', code='1002', type=AccountType.ASSET, currency='SGD'); db.add_all([cash, checking]); await db.flush(); first_doc = await _seed_statement(db, user_id, account_id=cash.id, file_hash='ac2888_first_stmt'); second_doc = await _seed_statement(db, user_id, account_id=cash.id, file_hash='ac2888_second_stmt'); checking_doc = await _seed_statement(db, user_id, account_id=checking.id, file_hash='ac2888_checking_stmt'); out_txn = await _seed_txn(db, user_id, first_doc, description='FAST PAYMENT TO BANK B', amount=Decimal('500.00'), direction='OUT', txn_date=date(2025, 1, 10)); await _share_row(db, out_txn, second_doc); in_txn = await _seed_txn(db, user_id, checking_doc, description='FAST PAYMENT FROM BANK A', amount=Decimal('500.00'), direction='IN', txn_date=date(2025, 1, 11)); first_id = await _statement_id_of(db, first_doc); second_id = await _statement_id_of(db, second_doc); matches = await execute_matching(db, user_id=user_id, currency='SGD'); assert {match.atomic_txn_id for match in matches} == {out_txn.id, in_txn.id}; out_match = next((match for match in matches if match.atomic_txn_id == out_txn.id)); out_entry_id = UUID(out_match.journal_entry_ids[0]); assert (await db.get(JournalEntry, out_entry_id)).source_id == out_txn.id; await db.commit(); await reject_statement_workflow(db, second_id, user_id, dependencies=posting_dependencies()); assert await _entry_status(db, out_entry_id) is JournalEntryStatus.RECONCILED; assert await _match_status(db, out_txn.id) is ReconciliationStatus.AUTO_ACCEPTED; await reject_statement_workflow(db, first_id, user_id, dependencies=posting_dependencies()); assert await _entry_status(db, out_entry_id) is JournalEntryStatus.VOID; assert await _match_status(db, out_txn.id) is ReconciliationStatus.SUPERSEDED
async def test_retire_of_unapproved_statement_with_unreadable_result_still_retires(db: AsyncSession, test_user): 'AC-extraction.2888.2'; statement_id = await _seed_statement_with_unreadable_result(db, test_user.id, status=BankStatementStatus.PARSED); retired = await retire_statement(db, RetireStatementCommand(statement_id=statement_id, user_id=test_user.id), dependencies=posting_dependencies()); assert retired.status is BankStatementStatus.RETIRED; assert await _status_of(db, statement_id) is BankStatementStatus.RETIRED
async def test_retire_of_approved_statement_with_unreadable_result_raises(db: AsyncSession, test_user):
    'AC-extraction.2888.2'; statement_id = await _seed_statement_with_unreadable_result(db, test_user.id, status=BankStatementStatus.APPROVED)
    with pytest.raises(ValueError, match='unsupported statement extraction schema version: 999'): await retire_statement(db, RetireStatementCommand(statement_id=statement_id, user_id=test_user.id), dependencies=posting_dependencies())
async def test_two_concurrent_retires_of_statements_that_share_a_row_release_the_row(db: AsyncSession, db_engine, test_user):
    'AC-extraction.2888.1'; shared = await _seed_posted_original_and_duplicate(db, test_user.id, duplicate_status=BankStatementStatus.APPROVED); maker = async_sessionmaker(db_engine, expire_on_commit=False)
    async with maker() as first, maker() as second:
        await retire_statement(first, RetireStatementCommand(statement_id=shared.original_id, user_id=test_user.id), dependencies=posting_dependencies()); second_retire = asyncio.create_task(retire_statement(second, RetireStatementCommand(statement_id=shared.duplicate_id, user_id=test_user.id), dependencies=posting_dependencies()))
        try: finished, _pending = await asyncio.wait({second_retire}, timeout=1.0); assert not finished, 'release 2 must wait for the advisory lock of release 1'; await first.commit(); await asyncio.wait_for(second_retire, timeout=10); await second.commit()
        finally:
            second_retire.cancel() if not second_retire.done() else None
            with contextlib.suppress(asyncio.CancelledError, Exception): await second_retire
    async with maker() as verification: assert await _status_of(verification, shared.original_id) is BankStatementStatus.RETIRED; assert await _status_of(verification, shared.duplicate_id) is BankStatementStatus.RETIRED; assert await _entry_status(verification, shared.entry_id) is JournalEntryStatus.VOID
async def test_release_takes_the_user_scoped_advisory_lock(db: AsyncSession, test_user): 'AC-extraction.2888.1'; from src.extraction.extension.statement_posting import release_statement_ledger_effects; shared = await _seed_posted_original_and_duplicate(db, test_user.id, duplicate_status=BankStatementStatus.PARSED); lock_count = text("SELECT count(*) FROM pg_locks WHERE locktype = 'advisory' AND pid = pg_backend_pid() AND ((classid::bigint << 32) | objid::bigint) = hashtextextended(:key, 0)"); key = {'key': f'statement-release:{test_user.id}'}; statement = await db.get(StatementSummary, shared.original_id); assert statement is not None; before = (await db.execute(lock_count, key)).scalar_one(); voided = await release_statement_ledger_effects(db, statement, test_user.id, was_approved=True, reason='Statement retired', dependencies=posting_dependencies()); after = (await db.execute(lock_count, key)).scalar_one(); assert voided == 1; assert after >= before + 1
